import {parseData,mappedEntries} from './engine.js';
let staged;
self.onmessage=event=>{const {id,action,text,type,map,header}=event.data;try{if(action==='preview'){staged=parseData(text,type);if(staged.config){self.postMessage({id,done:true,value:staged});return;}self.postMessage({id,done:true,value:{columns:staged.columns,rows:staged.rows.slice(0,8),rawRows:staged.rawRows?.slice(0,8),rowCount:staged.rows.length,rawRowCount:staged.rawRows?.length,worker:true}});}else if(action==='entries'){if(!staged||staged.config)throw Error('Preview your data first.');const rows=staged.rawRows&&!header?staged.rawRows:staged.rows;for(let start=0;start<rows.length;start+=10000){const entries=mappedEntries(rows.slice(start,start+10000),map);self.postMessage({id,batch:entries,progress:Math.min(1,(start+10000)/rows.length)});}self.postMessage({id,done:true});}}catch(e){self.postMessage({id,error:e.message||'This import could not be read.'});}};
